css:
.fx-btn-solid-blue-md-0039 {
  padding: 0.65rem 1.4rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  border: none;
  border-radius: 0.55rem;
  cursor: pointer;
  background: #3b82f6;
  box-shadow: 0 4px 14px 0 rgba(59,130,246, 0.35);
  transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
}
.fx-btn-solid-blue-md-0039:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 22px 0 rgba(59,130,246, 0.45);
  filter: brightness(1.08);
}
.fx-btn-solid-blue-md-0039:active { transform: translateY(0); }

.fx-btn-grad-ocean-md-0111 {
  padding: 0.65rem 1.4rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  border: none;
  border-radius: 0.55rem;
  cursor: pointer;
  background: linear-gradient(120deg, #0ea5e9, #6366f1);
  background-size: 200% 200%;
  background-position: 0% 50%;
  box-shadow: 0 4px 14px 0 rgba(0,0,0,0.18);
  transition: background-position 0.5s ease, transform 0.2s ease, box-shadow 0.3s ease;
}
.fx-btn-grad-ocean-md-0111:hover {
  background-position: 100% 50%;
  transform: translateY(-2px);
  box-shadow: 0 10px 24px 0 rgba(0,0,0,0.25);
}

.fx-btn-outline-blue-md-0213 {
  padding: 0.65rem 1.4rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: #3b82f6;
  background: transparent;
  border: 2px solid #3b82f6;
  border-radius: 0.55rem;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: color 0.3s ease, box-shadow 0.3s ease;
  z-index: 0;
}
.fx-btn-outline-blue-md-0213::before {
  content: '';
  position: absolute;
  inset: 0;
  background: #3b82f6;
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
  z-index: -1;
}
.fx-btn-outline-blue-md-0213:hover { color: #fff; box-shadow: 0 6px 18px 0 rgba(59,130,246, 0.35); }
.fx-btn-outline-blue-md-0213:hover::before { transform: scaleX(1); }

.fx-btn-glow-blue-md-0315 {
  padding: 0.65rem 1.4rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  border: none;
  border-radius: 0.55rem;
  cursor: pointer;
  background: #3b82f6;
  position: relative;
  transition: transform 0.2s ease;
}
.fx-btn-glow-blue-md-0315::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 0.55rem;
  box-shadow: 0 0 0 0 rgba(59,130,246, 0.7);
  animation: fx-btn-glow-blue-md-0315-pulse 1.8s infinite;
}
@keyframes fx-btn-glow-blue-md-0315-pulse {
  0%   { box-shadow: 0 0 0 0 rgba(59,130,246, 0.6); }
  70%  { box-shadow: 0 0 0 14px rgba(59,130,246, 0); }
  100% { box-shadow: 0 0 0 0 rgba(59,130,246, 0); }
}
.fx-btn-glow-blue-md-0315:hover { transform: translateY(-2px); }

.fx-btn-sheen-ocean-md-0387 {
  padding: 0.65rem 1.4rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: #fff;
  border: none;
  border-radius: 0.55rem;
  cursor: pointer;
  background: linear-gradient(120deg, #0ea5e9, #6366f1);
  position: relative;
  overflow: hidden;
  transition: transform 0.2s ease;
}
.fx-btn-sheen-ocean-md-0387::before {
  content: '';
  position: absolute;
  top: 0; left: -75%;
  width: 50%; height: 100%;
  background: linear-gradient(120deg, transparent, rgba(255,255,255,0.45), transparent);
  transform: skewX(-20deg);
  transition: left 0.6s ease;
}
.fx-btn-sheen-ocean-md-0387:hover::before { left: 125%; }
.fx-btn-sheen-ocean-md-0387:hover { transform: translateY(-2px); }

.fx-ld-spin-blue-norm-0489 {
  width: 38px; height: 38px;
  border: 4px solid rgba(59,130,246, 0.2);
  border-top-color: #3b82f6;
  border-radius: 50%;
  animation: fx-ld-spin-blue-norm-0489-rot 1s linear infinite;
}
@keyframes fx-ld-spin-blue-norm-0489-rot { to { transform: rotate(360deg); } }

.fx-ld-dots-ocean-norm-0561 { display: inline-flex; gap: 6px; }
.fx-ld-dots-ocean-norm-0561 span {
  width: 10px; height: 10px;
  border-radius: 50%;
  background: #0ea5e9;
  animation: fx-ld-dots-ocean-norm-0561-bounce 1s ease-in-out infinite;
}
.fx-ld-dots-ocean-norm-0561 span:nth-child(2) { background: #6366f1; animation-delay: 0.15s; }
.fx-ld-dots-ocean-norm-0561 span:nth-child(3) { animation-delay: 0.3s; }
@keyframes fx-ld-dots-ocean-norm-0561-bounce {
  0%, 80%, 100% { transform: translateY(0); opacity: 0.6; }
  40% { transform: translateY(-10px); opacity: 1; }
}

.fx-ld-pulse-blue-norm-0663 {
  width: 36px; height: 36px;
  border-radius: 50%;
  background: #3b82f6;
  animation: fx-ld-pulse-blue-norm-0663-pulse 1s ease-in-out infinite;
}
@keyframes fx-ld-pulse-blue-norm-0663-pulse {
  0%, 100% { transform: scale(0.6); opacity: 0.6; box-shadow: 0 0 0 0 rgba(59,130,246, 0.6); }
  50%      { transform: scale(1);   opacity: 1;   box-shadow: 0 0 0 12px rgba(59,130,246, 0); }
}

.fx-ld-bars-ocean-norm-0747 { display: inline-flex; gap: 4px; align-items: flex-end; height: 32px; }
.fx-ld-bars-ocean-norm-0747 span {
  width: 5px; height: 100%;
  background: #06b6d4;
  border-radius: 3px;
  animation: fx-ld-bars-ocean-norm-0747-eq 1s ease-in-out infinite;
}
.fx-ld-bars-ocean-norm-0747 span:nth-child(2) { background: #3b82f6; animation-delay: 0.1s; }
.fx-ld-bars-ocean-norm-0747 span:nth-child(3) { animation-delay: 0.2s; }
.fx-ld-bars-ocean-norm-0747 span:nth-child(4) { background: #6366f1; animation-delay: 0.3s; }
.fx-ld-bars-ocean-norm-0747 span:nth-child(5) { animation-delay: 0.4s; }
@keyframes fx-ld-bars-ocean-norm-0747-eq {
  0%, 100% { transform: scaleY(0.3); }
  50%      { transform: scaleY(1); }
}

.fx-card-lift-blue-slate-0823 {
  background: #1e293b;
  border: 1px solid #334155;
  border-top: 4px solid #3b82f6;
  border-radius: 0.6rem;
  padding: 1.25rem;
  color: #e2e8f0;
  width: 220px;
  box-shadow: 0 4px 14px rgba(0,0,0,0.15);
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.fx-card-lift-blue-slate-0823 h4 { margin: 0 0 0.4rem; font-size: 1rem; color: #60a5fa; }
.fx-card-lift-blue-slate-0823 p  { margin: 0; font-size: 0.85rem; opacity: 0.8; }
.fx-card-lift-blue-slate-0823:hover {
  transform: translateY(-6px);
  box-shadow: 0 18px 32px rgba(59,130,246, 0.25);
}

.fx-card-gb-ocean-slate-0919 {
  position: relative;
  background: #1e293b;
  border-radius: 0.7rem;
  padding: 1.25rem;
  color: #e2e8f0;
  width: 220px;
}
.fx-card-gb-ocean-slate-0919::before {
  content: '';
  position: absolute;
  inset: -2px;
  border-radius: 0.8rem;
  background: linear-gradient(120deg, #0ea5e9, #6366f1, #0ea5e9);
  background-size: 200% 200%;
  z-index: -1;
  animation: fx-card-gb-ocean-slate-0919-shift 3s linear infinite;
}
@keyframes fx-card-gb-ocean-slate-0919-shift { to { background-position: 200% 0; } }
.fx-card-gb-ocean-slate-0919 h4 { margin: 0 0 0.4rem; font-size: 1rem; color: #0ea5e9; }
.fx-card-gb-ocean-slate-0919 p  { margin: 0; font-size: 0.85rem; opacity: 0.8; }

.fx-txt-grad-ocean-md-1015 {
  margin: 0;
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  background: linear-gradient(120deg, #0ea5e9, #6366f1);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.fx-txt-anim-ocean-md-1099 {
  margin: 0;
  font-size: 2rem;
  font-weight: 800;
  background: linear-gradient(90deg, #06b6d4, #3b82f6, #6366f1, #06b6d4);
  background-size: 300% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: fx-txt-anim-ocean-md-1099-shift 4s linear infinite;
}
@keyframes fx-txt-anim-ocean-md-1099-shift { to { background-position: 300% 0; } }

.fx-txt-glow-blue-md-1165 {
  margin: 0;
  font-size: 2rem;
  font-weight: 800;
  color: #3b82f6;
  text-shadow:
    0 0 6px rgba(59,130,246, 0.6),
    0 0 14px rgba(59,130,246, 0.4),
    0 0 28px rgba(59,130,246, 0.2);
}

.fx-txt-underline-ocean-md-1233 {
  font-size: 1.6rem;
  font-weight: 700;
  color: #fff;
  text-decoration: none;
  position: relative;
  cursor: pointer;
}
.fx-txt-underline-ocean-md-1233::after {
  content: '';
  position: absolute;
  left: 0; bottom: -4px;
  width: 100%; height: 3px;
  background: linear-gradient(90deg, #0ea5e9, #6366f1);
  transform: scaleX(0);
  transform-origin: left;
  transition: transform 0.3s ease;
}
.fx-txt-underline-ocean-md-1233:hover::after { transform: scaleX(1); }

.fx-bg-grad-ocean-norm-1297 {
  width: 100%; height: 100%;
  min-height: 160px;
  border-radius: 0.5rem;
  background: linear-gradient(120deg, #06b6d4, #3b82f6, #6366f1, #06b6d4);
  background-size: 300% 300%;
  animation: fx-bg-grad-ocean-norm-1297-flow 1s ease infinite;
}
@keyframes fx-bg-grad-ocean-norm-1297-flow {
  0%   { background-position: 0% 50%; }
  50%  { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.fx-bg-glow-blue-slate-1373 {
  width: 100%; height: 100%;
  min-height: 160px;
  border-radius: 0.5rem;
  background:
    radial-gradient(circle at 30% 30%, rgba(59,130,246, 0.45), transparent 50%),
    radial-gradient(circle at 70% 70%, rgba(59,130,246, 0.25), transparent 50%),
    #0f172a;
}

.fx-bg-stripe-ocean-diagonal-1465 {
  width: 100%; height: 100%;
  min-height: 160px;
  border-radius: 0.5rem;
  background: repeating-linear-gradient(45deg, #0ea5e9 0 14px, #6366f1 14px 28px);
}

.fx-bg-stripe-ocean-vertical-1467 {
  width: 100%; height: 100%;
  min-height: 160px;
  border-radius: 0.5rem;
  background: repeating-linear-gradient(90deg, #0ea5e9 0 14px, #6366f1 14px 28px);
}

.fx-bg-conic-ocean-1515 {
  width: 100%; height: 100%;
  min-height: 160px;
  border-radius: 0.5rem;
  background: conic-gradient(from 0deg, #06b6d4, #3b82f6, #6366f1, #06b6d4);
  animation: fx-bg-conic-ocean-1515-rot 6s linear infinite;
}
@keyframes fx-bg-conic-ocean-1515-rot { to { transform: rotate(360deg); } }

.fx-inp-fl-blue-md-1574 { position: relative; width: 220px; }
.fx-inp-fl-blue-md-1574 input {
  width: 100%;
  padding: 0.65rem 1.4rem;
  font-size: 0.95rem;
  color: #e5e7eb;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.18);
  border-radius: 0.55rem;
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.fx-inp-fl-blue-md-1574 input:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 3px rgba(59,130,246, 0.25);
}
.fx-inp-fl-blue-md-1574 label {
  position: absolute;
  left: 0.8rem; top: 50%;
  transform: translateY(-50%);
  font-size: 0.95rem;
  color: #9ca3af;
  pointer-events: none;
  transition: all 0.2s ease;
  background: #3b82f6;
  padding: 0 4px;
  border-radius: 3px;
  color: #fff;
}
.fx-inp-fl-blue-md-1574 input:focus + label,
.fx-inp-fl-blue-md-1574 input:not(:placeholder-shown) + label {
  top: 0;
  font-size: 0.7rem;
  transform: translateY(-50%);
}

.fx-inp-ug-ocean-md-1678 {
  width: 220px;
  padding: 0.65rem 1.4rem;
  font-size: 0.95rem;
  color: #e5e7eb;
  background: transparent;
  border: none;
  border-bottom: 2px solid rgba(255,255,255,0.25);
  outline: none;
  position: relative;
}
.fx-inp-ug-ocean-md-1678::after { content: ''; }
/* Use wrapper trick: simulate via background-image */
.fx-inp-ug-ocean-md-1678 {
  background-image: linear-gradient(90deg, #0ea5e9, #6366f1);
  background-size: 0% 2px;
  background-repeat: no-repeat;
  background-position: 0 100%;
  transition: background-size 0.3s ease, border-color 0.3s ease;
}
.fx-inp-ug-ocean-md-1678:focus {
  border-bottom-color: transparent;
  background-size: 100% 2px;
}

.fx-hov-zoom-ocean-slate-1766 {
  width: 180px; height: 120px;
  border-radius: 0.6rem;
  overflow: hidden;
  border: 1px solid #334155;
  background: #1e293b;
}
.fx-hov-zoom-ocean-slate-1766-inner {
  width: 100%; height: 100%;
  background: linear-gradient(120deg, #06b6d4, #3b82f6, #6366f1);
  transition: transform 0.4s ease;
}
.fx-hov-zoom-ocean-slate-1766:hover .fx-hov-zoom-ocean-slate-1766-inner { transform: scale(1.12); }

.fx-nav-pill-blue-slate-1854 {
  display: inline-flex;
  gap: 4px;
  padding: 4px;
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 999px;
}
.fx-nav-pill-blue-slate-1854 a {
  padding: 0.4rem 0.9rem;
  font-size: 0.85rem;
  font-weight: 500;
  color: #e2e8f0;
  border-radius: 999px;
  cursor: pointer;
  transition: color 0.2s ease, background 0.2s ease;
}
.fx-nav-pill-blue-slate-1854 a:hover { color: #60a5fa; }
.fx-nav-pill-blue-slate-1854 a.active {
  color: #fff;
  background: #3b82f6;
  box-shadow: 0 2px 8px rgba(59,130,246, 0.45);
}

.fx-nav-underline-ocean-1944 { display: inline-flex; gap: 1.5rem; }
.fx-nav-underline-ocean-1944 a {
  position: relative;
  font-size: 0.95rem;
  font-weight: 600;
  color: #9ca3af;
  cursor: pointer;
  padding-bottom: 6px;
  transition: color 0.2s ease;
}
.fx-nav-underline-ocean-1944 a:hover { color: #fff; }
.fx-nav-underline-ocean-1944 a.active { color: #fff; }
.fx-nav-underline-ocean-1944 a.active::after {
  content: '';
  position: absolute;
  left: 0; bottom: 0;
  width: 100%; height: 2px;
  background: linear-gradient(90deg, #0ea5e9, #6366f1);
  border-radius: 2px;
}

.fx-div-line-ocean-thin-1972 {
  width: 100%; max-width: 280px;
  display: flex; flex-direction: column; gap: 0.6rem;
  color: #cbd5e1; font-family: system-ui, sans-serif;
}
.fx-div-line-ocean-thin-1972 .pre {
  margin: 0;
  font-size: 0.85rem; font-weight: 700; color: #f1f5f9;
  letter-spacing: -0.01em;
}
.fx-div-line-ocean-thin-1972 .post {
  margin: 0;
  font-size: 0.78rem; color: #94a3b8; line-height: 1.4;
}
.fx-div-line-ocean-thin-1972 .rule {
  width: 100%; height: 1px;
  background: linear-gradient(90deg, transparent, #0ea5e9, #6366f1, transparent);
  border-radius: 1px;
}

.fx-div-line-ocean-med-1974 {
  width: 100%; max-width: 280px;
  display: flex; flex-direction: column; gap: 0.6rem;
  color: #cbd5e1; font-family: system-ui, sans-serif;
}
.fx-div-line-ocean-med-1974 .pre {
  margin: 0;
  font-size: 0.85rem; font-weight: 700; color: #f1f5f9;
  letter-spacing: -0.01em;
}
.fx-div-line-ocean-med-1974 .post {
  margin: 0;
  font-size: 0.78rem; color: #94a3b8; line-height: 1.4;
}
.fx-div-line-ocean-med-1974 .rule {
  width: 100%; height: 2px;
  background: linear-gradient(90deg, transparent, #0ea5e9, #6366f1, transparent);
  border-radius: 2px;
}

.fx-div-line-ocean-thick-1976 {
  width: 100%; max-width: 280px;
  display: flex; flex-direction: column; gap: 0.6rem;
  color: #cbd5e1; font-family: system-ui, sans-serif;
}
.fx-div-line-ocean-thick-1976 .pre {
  margin: 0;
  font-size: 0.85rem; font-weight: 700; color: #f1f5f9;
  letter-spacing: -0.01em;
}
.fx-div-line-ocean-thick-1976 .post {
  margin: 0;
  font-size: 0.78rem; color: #94a3b8; line-height: 1.4;
}
.fx-div-line-ocean-thick-1976 .rule {
  width: 100%; height: 4px;
  background: linear-gradient(90deg, transparent, #0ea5e9, #6366f1, transparent);
  border-radius: 4px;
}

.fx-div-dashed-blue-2062 {
  width: 100%; max-width: 280px;
  display: flex; align-items: center; gap: 0.75rem;
  color: #cbd5e1; font-family: system-ui, sans-serif;
}
.fx-div-dashed-blue-2062 .label {
  font-size: 0.7rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.08em;
  color: #3b82f6;
  white-space: nowrap;
}
.fx-div-dashed-blue-2062 .rule {
  flex: 1; height: 0;
  border-top: 2px dashed #3b82f6;
  opacity: 0.85;
}
.fx-div-dashed-blue-2062 .meta {
  font-size: 0.7rem; color: #64748b;
  white-space: nowrap;
}

.fx-div-dotted-blue-2064 {
  width: 100%; max-width: 280px;
  display: flex; align-items: center; gap: 0.75rem;
  color: #cbd5e1; font-family: system-ui, sans-serif;
}
.fx-div-dotted-blue-2064 .label {
  font-size: 0.7rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.08em;
  color: #3b82f6;
  white-space: nowrap;
}
.fx-div-dotted-blue-2064 .rule {
  flex: 1; height: 0;
  border-top: 2px dotted #3b82f6;
  opacity: 0.85;
}
.fx-div-dotted-blue-2064 .meta {
  font-size: 0.7rem; color: #64748b;
  white-space: nowrap;
}

.fx-div-tri-ocean-2112 {
  width: 100%; max-width: 280px;
  display: flex; align-items: center; gap: 8px;
}
.fx-div-tri-ocean-2112 .dot {
  width: 8px; height: 8px; border-radius: 50%;
  background: #06b6d4; flex-shrink: 0;
  box-shadow: 0 0 8px #06b6d4;
}
.fx-div-tri-ocean-2112 .bar {
  flex: 1; height: 3px; border-radius: 2px;
}
.fx-div-tri-ocean-2112 .bar:nth-child(2) { background: #06b6d4; }
.fx-div-tri-ocean-2112 .bar:nth-child(3) { background: #3b82f6; }
.fx-div-tri-ocean-2112 .bar:nth-child(4) { background: #6366f1; }

.fx-bdg-solid-blue-md-2152 {
  display: flex; flex-direction: column; gap: 0.5rem;
  font-family: system-ui, sans-serif;
}
.fx-bdg-solid-blue-md-2152 .hdr {
  font-size: 0.7rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.08em;
  color: #94a3b8;
}
.fx-bdg-solid-blue-md-2152 .row { display: flex; flex-wrap: wrap; gap: 0.4rem; }
.fx-bdg-solid-blue-md-2152 .badge {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.65rem;
  font-size: 0.75rem;
  font-weight: 700;
  color: #fff;
  background: #3b82f6;
  border-radius: 999px;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.fx-bdg-out-blue-md-2254 {
  display: flex; flex-direction: column; gap: 0.5rem;
  font-family: system-ui, sans-serif;
}
.fx-bdg-out-blue-md-2254 .hdr {
  font-size: 0.7rem; font-weight: 700;
  text-transform: uppercase; letter-spacing: 0.08em;
  color: #94a3b8;
}
.fx-bdg-out-blue-md-2254 .row { display: flex; flex-wrap: wrap; gap: 0.4rem; }
.fx-bdg-out-blue-md-2254 .badge {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.65rem;
  font-size: 0.75rem;
  font-weight: 700;
  color: #3b82f6;
  background: rgba(59,130,246, 0.1);
  border: 1px solid #3b82f6;
  border-radius: 999px;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.fx-tgl-ios-blue-md-2356 { display: flex; flex-direction: column; gap: 0.7rem; color: #cbd5e1; font-family: system-ui, sans-serif; }
.fx-tgl-ios-blue-md-2356 .row { display: inline-flex; align-items: center; gap: 0.6rem; cursor: pointer; }
.fx-tgl-ios-blue-md-2356 input { display: none; }
.fx-tgl-ios-blue-md-2356 .track {
